(()=>{
  'use strict';
  const pagesMode=!!window.JiaoyingPages,apiFetch=pagesMode?window.JiaoyingPages.fetch:(...args)=>fetch(...args),EventStream=pagesMode?window.JiaoyingPages.EventSource:(typeof EventSource==='function'?EventSource:null);
  const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let state=null,connected=false,busy=false,view=location.hash==='#field'?'field':'command',tab='execution',routeChoice='all',showAlternative=false,chatDraft='',messages=[],autoSpeech=false,speechNote='',lastSpeech='',toastTimer,modal=null;
  let mapMode='geographic',voiceTarget='chat';
  let eventStream=null,liveConnected=false,fieldVehicle='',fieldHousehold='',fieldLocation='',fieldUtterance='',fieldSource='text',fieldPrepared=null,fieldConfirmed=false,fieldReceipt=null,allFieldEvents=false,fieldVoiceReady=false,nextStreamAttempt=0;

  let fieldWorkspace='village',villagePrepared=null,villageReceipt='',villageFilter='',villageVoiceReady=false;
  const villageForm={villageId:'',pickupId:'',mode:'increment',targetId:'',text:'',observedAt:'',source:'text'};
  const form={kind:'road',location:'',text:'',people:'',wheelchair:false,assistance:false,reporter:'现场演示员',checked:false};
  const stageNames={waiting:'待接送',boarded:'已上车',arrived:'到达待核验',verified:'已人工核验'};
  const reportNames={road:'道路受阻',people:'新增人员',medical:'医疗协助',hazard:'险情变化',progress:'任务进展',other:'其他反馈'};
  const statusNames={pending:'待核实',accepted:'已采纳',rejected:'未采纳',coordination:'待协调',resolved:'已处理'};
  const d=()=>state.data,s=()=>d().scenario;
  const btn=(label,action,extra='',kind='')=>`<button class="${kind}" data-ac="${action}" ${extra} ${busy?'disabled':''}>${label}</button>`;
  const badge=(label,color='')=>`<span class="badge ${color}">${esc(label)}</span>`;
  const head=(title,sub='',right='')=>`<div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;
  const nodeName=id=>s().nodes.find(n=>n.id===id)?.label||id;
  const homeName=id=>s().households.find(h=>h.id===id)?.name||id;
  const roadName=id=>{const e=s().edges.find(e=>e.id===id);return e?(id==='east'?'演练东桥':id==='north'?'演练北桥':`${nodeName(e.from)}—${nodeName(e.to)}`):id;};
  const locName=id=>s().edges.some(e=>e.id===id)?roadName(id):nodeName(id);
  const clock=iso=>new Date(iso).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
  const plan=()=>showAlternative&&d().alternative?d().alternative:d().plan;
  function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
  const voice=JiaoyingVoice.create({Recognition:window.SpeechRecognition||window.webkitSpeechRecognition,secure:window.isSecureContext,getText:()=>voiceTarget==='village'?villageForm.text:voiceTarget==='field-agent'?fieldUtterance:voiceTarget==='report'?form.text:chatDraft,onText:text=>{if(voiceTarget==='village'){villageForm.text=text;villageForm.source='voice';prepareVillage(false);villageVoiceReady=true;}else if(voiceTarget==='field-agent'){fieldUtterance=text;fieldSource='voice';prepareFieldUtterance(false);fieldVoiceReady=true;}else if(voiceTarget==='report'){invalidateFieldDraft();form.text=text;form.checked=false;form.voiceFilled=true;}else chatDraft=text;},onChange:()=>{render();if(villageVoiceReady){villageVoiceReady=false;$('village-preview')?.scrollIntoView({block:'start'});highlightResult('village-preview');}if(fieldVoiceReady){fieldVoiceReady=false;$('field-preview')?.scrollIntoView({block:'start'});highlightResult('field-preview');}}});
  let speechToken=0,activeUtterance=null,speechTimer=null;
  function stopSpeech(){speechToken++;clearTimeout(speechTimer);activeUtterance=null;window.speechSynthesis?.cancel();}
  function speech(text){
    if(voice.active()){speechNote='语音输入期间暂停播报，结束后可点击补播。';updateSpeechStatus();return;}
    if(!('speechSynthesis' in window)){speechNote='此浏览器不支持语音播报，可阅读事件播报。';render();return;}
    stopSpeech();const token=speechToken,utterance=new SpeechSynthesisUtterance(text);activeUtterance=utterance;utterance.lang='zh-CN';utterance.rate=1;
    const voices=window.speechSynthesis.getVoices(),chosen=voices.find(v=>v.localService&&v.lang.toLowerCase().startsWith('zh'))||voices.find(v=>v.lang.toLowerCase().startsWith('zh'));if(chosen)utterance.voice=chosen;
    const finish=note=>{if(token!==speechToken)return;clearTimeout(speechTimer);activeUtterance=null;speechNote=note;updateSpeechStatus();};
    speechNote='已请求系统播报…';utterance.onstart=()=>{if(token===speechToken){speechNote='正在播报…';updateSpeechStatus();}};
    utterance.onend=()=>finish('播报结束');utterance.onerror=()=>finish('未能播报，请检查浏览器语音服务。');
    speechTimer=setTimeout(()=>{if(token===speechToken){stopSpeech();speechNote='语音服务未反馈完成；可点击重试或阅读事件文字。';updateSpeechStatus();}},Math.max(20000,text.length*350+10000));
    window.speechSynthesis.speak(utterance);updateSpeechStatus();
  }
  function updateSpeechStatus(){if($('speech-status'))$('speech-status').textContent=speechNote;}
  function acceptState(next){
    if(!next.data)return;const previous=state;if(previous?.session===next.session&&previous.data.revision>next.data.revision)return;
    if(previous?.session===next.session&&previous.data.revision===next.data.revision&&connected){connectEvents(next);return;}
    state=next;connected=true;if(showAlternative&&!d().alternative)showAlternative=false;
    if(previous&&previous.session!==next.session){messages=[];lastSpeech='';notify(pagesMode?'浏览器演练已更新，已载入当前记录；未提交的输入仍保留。':'本地服务已重启，已载入新演练；未提交的输入仍保留。');}
    if(autoSpeech&&previous&&d().lastAnnouncement!==lastSpeech){lastSpeech=d().lastAnnouncement;speech(lastSpeech);}connectEvents(next);render();
    const incoming=d().fieldEvents?.[0],oldEvent=previous?.data.fieldEvents?.[0];
    if(view==='command'&&previous?.session===state.session&&incoming&&incoming.id!==oldEvent?.id){notify('现场更新：'+incoming.summary);window.JiaoyingMotion?.finish('现场确认已同步到指挥台');highlightResult('field-live');}
    if(view==='field'&&previous?.session===state.session){const changed=(d().villageReports||[]).find(r=>{const old=previous.data.villageReports?.find(x=>x.id===r.id);return old&&(old.status!==r.status||old.needsInfo!==r.needsInfo);});if(changed){notify('指挥台已处理村级上报 '+changed.id+'，请查看处理结果。');highlightResult('village-reports');}}
    if(view==='field'&&previous?.session===state.session){const updated=d().reports.find(r=>{const before=previous.data.reports.find(x=>x.id===r.id);return before&&before.status!==r.status;});if(updated){notify('指挥台已更新 '+updated.id+'：'+statusNames[updated.status]);highlightResult('reports-panel');}}

  }
  function connectEvents(snapshot=state){
    if(eventStream||Date.now()<nextStreamAttempt||!snapshot?.capabilities?.realtimeEvents||typeof EventStream!=='function')return;
    eventStream=new EventStream('/api/v3/events');
    eventStream.addEventListener('state',event=>{try{const next=JSON.parse(event.data);if(!next?.data||!next.session)return;const changed=!liveConnected;liveConnected=true;acceptState(next);if(changed)render();}catch(_){liveConnected=false;render();}});
    eventStream.onerror=()=>{if(liveConnected){liveConnected=false;render();}if(eventStream?.readyState===EventStream.CLOSED){eventStream.close();eventStream=null;nextStreamAttempt=Date.now()+5000;}poll(true);};
  }
  async function poll(force=false){
    if(busy||(!force&&liveConnected))return;try{const url='/api/v3/state'+(state?`?after=${d().revision}&session=${encodeURIComponent(state.session)}`:'');const res=await apiFetch(url,{signal:AbortSignal.timeout(4000),cache:'no-store'});if(!res.ok)throw new Error('服务不可用');const result=await res.json();const reconnect=!connected;connected=true;if(!result.unchanged)acceptState(result);else if(reconnect)render();connectEvents();}catch(_){if(!liveConnected&&(connected||!state)){connected=false;render();}}
  }
  const actionFeedback={
    generate:['正在计算调度草案','调度草案已生成，等待人工核对','planning-panel'],
    weather:['正在更新演练情景','演练天气与复核结果已更新','weather-panel'],
    report:['正在提交现场反馈','反馈已提交，等待指挥端核实','reports-panel'],
    confirm:['正在保存模拟发布','方案已模拟发布','planning-panel'],
    review:['正在保存核实结论','核实结果已保存','reports-panel'],
    resolve:['正在登记处理结果','处理结果已保存','reports-panel'],
    edit:['正在更新资源并重新计算','资源和调度草案已更新','planning-panel'],
    contact:['正在登记联系结果','演练联系结果已保存','task-panel'],
    start:['正在启动模拟执行','模拟执行已开始','task-panel'],
    step:['正在登记执行进展','执行进展已更新','task-panel'],
    verify:['正在保存人工核验','人工核验结果已保存','task-panel'],
    reset:['正在重置合成演练','合成演练已重置','planning-panel'],
    'field-progress':['正在提交现场环节','现场环节已登记并同步','field-preview'],
    'village-report':['正在提交村级上报','村级上报已同步，等待指挥台核实','village-reports'],
    'village-review':['正在保存核实结论','村级台账与待接需求已更新','village-ledger'],
    'village-complete':['正在补齐接送信息','接送组已生成，待核对调度草案','planning-panel']
  };
  function highlightResult(id){const target=$(id);if(!target)return;target.classList.remove('result-highlight');void target.offsetWidth;target.classList.add('result-highlight');}
  async function action(name,payload={},revision=d().revision,session=state.session,requestId=crypto.randomUUID()){
    if(busy)throw new Error('请等待当前操作完成');if(!connected)throw new Error(pagesMode?'浏览器存储暂不可用，输入已保留，请恢复后重试':'本地服务已断开，输入已保留，请恢复连接后重试');
    const feedback=actionFeedback[name]||['正在保存演练操作','演练记录已保存',''];let completed=false;
    busy=true;window.JiaoyingMotion?.begin(feedback[0]);render();
    try{const response=await apiFetch('/api/v3/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:name,payload,expectedRevision:revision,session,requestId}),signal:AbortSignal.timeout(15000)});const result=await response.json();if(result.data)acceptState(result);if(!response.ok)throw new Error(result.error||'操作未完成');completed=true;window.JiaoyingMotion?.finish(feedback[1]);return result;}
    catch(error){const message=error.name==='TimeoutError'?'请求超时，先检查事件记录是否已生效，再重试。':error.message;window.JiaoyingMotion?.finish(message,'error');throw new Error(message);}
    finally{busy=false;render();if(completed)highlightResult(feedback[2]);}
  }
  function fieldViewState(){return {vehicleId:fieldVehicle,householdId:fieldHousehold,location:fieldLocation,utterance:fieldUtterance,prepared:fieldPrepared,confirmed:fieldConfirmed,receipt:fieldReceipt,reporter:form.reporter,voiceState:voice.state(),busy,connected:connected&&!!state.capabilities?.realtimeEvents,live:liveConnected,allEvents:allFieldEvents};}
  const fieldHelpers={head,btn,badge,voiceHTML};
  function fieldTasksHTML(){return JiaoyingFieldUI.tasks(state,fieldViewState(),fieldHelpers);}
  function fieldAgentHTML(){return JiaoyingFieldUI.assistant(state,fieldViewState(),fieldHelpers);}
  function fieldPreviewHTML(){return JiaoyingFieldUI.preview(state,fieldViewState(),fieldHelpers);}
  function fieldLiveHTML(){return JiaoyingFieldUI.live(state,fieldViewState(),fieldHelpers);}
  function fieldUpdateHTML(){if(!state.capabilities?.villageReporting)return '<div class="notice warn"><strong>此页面仍连接旧版服务</strong><p>请运行项目中的“启动V3.4演示.cmd”，使用 <a href="http://127.0.0.1:8767/#command">新版指挥台</a> 与 <a href="http://127.0.0.1:8767/#field">新版现场端</a> 完成即时联动。</p></div>';const e=d().fieldEvents?.[0];return view==='command'&&e?`<div class="field-update-bar"><span class="live-dot ${liveConnected?'is-live':''}"></span><strong>现场最新</strong><span>${esc(e.summary)}</span><small>${clock(e.time)}</small>${btn('查看现场实况','field-live','','small quiet')}</div>`:'';}
  function displayPrepared(result,origin,focus=true){fieldPrepared={...result,origin,revision:d().revision,session:state.session,requestId:crypto.randomUUID()};fieldConfirmed=false;if(focus){render();$('field-preview')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});highlightResult('field-preview');}}
  function prepareFieldUtterance(focus=true){
    if(!state||!window.JiaoyingFieldAssistant)return;
    const result=JiaoyingFieldAssistant.prepare(fieldUtterance,{data:d(),vehicleId:fieldVehicle,householdId:fieldHousehold,location:fieldLocation,reporter:form.reporter});
    if(result.proposal)result.proposal.payload.source=fieldSource;
    displayPrepared(result,'assistant',focus);
  }
  function prepareFieldQuick(stage,householdId){
    const route=d().activePlan?.routes.find(r=>r.vehicleId===fieldVehicle),v=s().vehicles.find(v=>v.id===fieldVehicle),house=s().households.find(h=>h.id===householdId);
    if(!route||!v)throw new Error('请先选择车辆，并等待指挥台发布任务');
    const label=JiaoyingFieldUI.stageNames[stage];if(!label)throw new Error('未识别的现场环节');
    const summary=`${v.name}：${label}${house?' · '+house.name+' '+house.people+' 人':''}${stage==='arrive'?' · '+s().shelters.find(x=>x.id===route.shelterId)?.name:''}`;
    displayPrepared({mode:'quick',intent:'progress',title:'确认现场环节',summary,proposal:{action:'field-progress',payload:{stage,vehicleId:fieldVehicle,planId:d().activePlan.id,...(householdId?{householdId}:{}),reporter:form.reporter,source:'quick',text:summary}},questions:[],warnings:[stage==='arrive'?'只登记到达，仍等待指挥台人工核验。':stage==='ack'?'仅确认接收任务，不表示已联系家庭或完成转移。':'请按现场事实确认；不会跳过未完成环节。'],evidence:['依据已发布方案 '+d().activePlan.id]},'quick');
  }
  function prepareManualReport(){
    if(voice.active())throw new Error('请先结束语音输入');if(!form.location||!form.text.trim())throw new Error('请选择位置并填写现场说明');
    displayPrepared({mode:'manual',intent:'report',title:'确认现场反馈',summary:'请核对下方内容；确认后指挥台将即时收到。',proposal:{action:'report',payload:{...form,source:form.voiceFilled?'voice':'manual'}},questions:[],warnings:['提交后等待指挥台核实；不会直接封路或确认人员安全。'],evidence:[]},'manual');
  }
  async function submitFieldPrepared(){
    if(!state.capabilities?.realtimeEvents)throw new Error('当前是旧版服务，请先使用新版启动器打开两个网页');
    if(voice.active())throw new Error('请先结束语音识别');const prepared=fieldPrepared;
    if(!prepared?.proposal||!fieldConfirmed)throw new Error('请先核对并勾选确认');
    if(prepared.session!==state.session||prepared.revision!==d().revision)throw new Error('演练已更新，请重新整理后核对');
    const payload={...prepared.proposal.payload,reporter:form.reporter};
    const result=await action(prepared.proposal.action,payload,prepared.revision,prepared.session,prepared.requestId);
    const event=result.data.fieldEvents?.[0];fieldReceipt={title:event?.summary||'现场记录已提交',detail:event?.reportId?'反馈编号 '+event.reportId+' · 等待指挥台核实。':payload.stage==='arrive'?'已登记到达，等待指挥台人工核验。':'可继续办理下一环节，指挥台已获得最新状态。',time:event?.time||new Date().toISOString()};
    if(fieldPrepared===prepared){fieldPrepared=null;fieldConfirmed=false;if(prepared.origin==='assistant')fieldUtterance='';if(prepared.origin==='manual'){form.text='';form.checked=false;form.voiceFilled=false;}}
    render();notify('现场记录已提交并同步。');$('field-preview')?.scrollIntoView({block:'start'});
  }
  function voiceHTML(target='chat'){const v=voice.state(),here=v.active&&voiceTarget===target,elsewhere=v.active&&!here;return `<div class="voice-controls">${btn(here?(v.phase==='starting'?'取消等待':v.phase==='stopping'?'整理中…':'结束识别'):target==='chat'?'语音提问':'语音输入','voice',`data-target="${target}" aria-pressed="${here}" ${!v.supported||elsewhere||v.phase==='stopping'?'disabled':''}`,target==='field-agent'?'primary':'')}${here?btn('取消本次','voice-cancel','','quiet'):'<span>普通话 · 核对后提交</span>'}</div><p class="voice-note" role="status">${esc(elsewhere?'另一处正在进行语音识别，请先结束。':v.note)}</p>${here?`<div class="voice-preview">${esc(v.preview||'正在等待语音…')}</div>`:''}<p class="voice-note muted">浏览器识别可能联网；本演示不保存录音。</p>`;}
  function titleHTML(){return `<div class="page-title"><div><span class="eyebrow">RUIAN / LOCAL EXERCISE</span><h1>${view==='field'?'现场任务与反馈':'瑞安防汛协同工作台'}</h1><p>浙江省瑞安市 · 真实地理底图 · 调度数据为合成演练</p></div><div class="actions no-print">${view==='command'?'<a class="button" href="./#field" target="_blank" rel="noopener">打开现场网页 ↗</a>':'<a class="button" href="./#command" target="_blank" rel="noopener">打开指挥网页 ↗</a>'}${btn(view==='field'?'语音协同助手':'与 AI 对话','focus-ai','','ai-entry')}${view==='command'?btn('村级台账','village-ledger'):''}${btn('接口与范围','settings')}${btn('导出报告','report','','primary')}</div></div><div class="statusline">${badge(connected?(pagesMode?'浏览器内同步 · 记录 ':liveConnected?'即时联动 · 记录 ':'轮询同步 · 记录 ')+d().revision:'连接中断 · 暂停提交',connected?'teal':'red')}${badge(d().phase==='preparation'?'出发前准备':'模拟执行中')}${badge('大模型未接入','gray')}<span class="muted">输入 v${d().inputVersion} / 执行记录 ${d().executionVersion} · ${pagesMode?'已保存在当前浏览器；不同设备不共享':'服务重启会重置演练'}</span></div>${pagesMode?'<div class="notice"><strong>GitHub 浏览器演练</strong> · 在同一浏览器打开指挥台和现场端即可联动。各位访客的数据彼此独立；演练内容仅保存在此浏览器，不会上传 GitHub。请仅输入模拟数据，清除浏览器数据会丢失记录。</div>':''}`;}
  function metricHTML(){const m=state.metrics;return `<div class="metrics"><div class="metric"><span>本次转移对象</span><strong>${m.people} <small>人</small></strong><small>${s().households.filter(h=>d().stage[h.id]!=='superseded').length} 个接送组 · 待接 ${m.waiting} 人</small></div><div class="metric"><span>已人工核验</span><strong>${m.verified} <small>人</small></strong><small>已上车 ${m.boarded} · 到达待核验 ${m.arrived}</small></div><div class="metric"><span>安置剩余容量</span><strong>${m.capacity} <small>人</small></strong><small>扣除已登记到达占用</small></div><div class="metric"><span>现场待核实</span><strong>${m.pendingReports} <small>条</small></strong><small>演练高风险对象 ${m.highRisk} 人</small></div></div>`;}
  function deltaHTML(){const change=d().lastDelta;if(!change)return '';const labels={people:'转移对象（人）',highRisk:'演练高风险对象（人）',capacity:'安置余位（人）',shortage:'总安置名额缺口（人）',closed:'封闭路段（条）',rainfall:'演练一小时雨量（mm）'};return `<div class="notice delta-strip"><strong>最近指标变化 · ${clock(change.time)}</strong><div class="actions">${change.rows.map(r=>`<span>${labels[r.key]} ${r.before} → ${r.after}（${r.delta>0?'+':''}${r.delta}）</span>`).join('')}</div><small>名额缺口仅反映总容量；车辆、道路与适配限制另外校验。</small></div>`;}
  function differenceHTML(p){const old=d().activePlan;if(!p||!old||p.id===old.id)return '';const key=r=>{if(!r)return '';const pending=r.stops.filter(x=>d().stage[x.id]==='waiting'),first=pending.length?r.stops.indexOf(pending[0]):r.stops.length;return JSON.stringify([pending.map(x=>x.id),r.shelterId,r.segments.slice(first).map(x=>x.edges)]);};const changed=p.routes.filter(r=>key(r)!==key(old.routes.find(x=>x.vehicleId===r.vehicleId)));return `<div class="notice"><strong>相对发布方案 ${esc(old.id)}</strong><p>${esc(d().plan?.trigger||'当前条件复核')}；${changed.length?changed.map(r=>esc(s().vehicles.find(v=>v.id===r.vehicleId).name)).join('、')+' 的剩余任务或路线有变化。':'分配与路线保持一致，无须因数值刷新反复切换。'}</p><small>请核对下方新安排与“当前发布方案”；已上车人员保持原车。备选仅适用于本次输入，条件变化需重新计算。</small></div>`;}
  function mapHTML(){const switcher=`<div class="map-switch" role="group" aria-label="地图视图">${btn('瑞安真实地图','map-mode',`data-id="geographic" aria-pressed="${mapMode==='geographic'}"`,mapMode==='geographic'?'active':'')}${btn('调度演练路网','map-mode',`data-id="exercise" aria-pressed="${mapMode==='exercise'}"`,mapMode==='exercise'?'active':'')}</div>`;return `<section class="panel geographic-panel">${head(mapMode==='geographic'?'瑞安市实际地图':'调度演练路网',mapMode==='geographic'?'城区 · 飞云江两岸，支持缩放 / 拖动浏览':'合成节点与演练计算结果',badge(mapMode==='geographic'?'真实地理数据':'合成演练',mapMode==='geographic'?'teal':'gray'))}${switcher}${mapMode==='geographic'?'<div id="geographic-map" class="geographic-map"><p class="empty">正在载入瑞安市真实地图…</p></div><p class="map-caption">真实底图用于认识地理位置。当前接送家庭、安置容量与调度路线仍属演练；点击“调度演练路网”查看计算。</p>':exerciseMapHTML()}</section>`;}
  function exerciseMapHTML(){
    const nodes=Object.fromEntries(s().nodes.map(n=>[n.id,n])),p=plan()||d().activePlan,colors=Object.fromEntries(s().vehicles.map(v=>[v.id,v.color]));
    const lines=s().edges.map(e=>`<g role="button" tabindex="0" data-ac="map-road" data-id="${e.id}" aria-label="${esc(roadName(e.id))}，${e.open?'开放':'封闭'}"><line class="map-road" x1="${nodes[e.from].x}" y1="${nodes[e.from].y}" x2="${nodes[e.to].x}" y2="${nodes[e.to].y}" stroke="${e.open?'#c8d5e6':'#bd5448'}" stroke-width="${e.open?5:7}" ${e.open?'':'stroke-dasharray="7 5"'}/><title>${esc(roadName(e.id))} · ${e.minutes} 分钟 · ${e.open?'开放':'封闭'}</title></g>`).join('');
    const routes=(p?.routes||[]).filter(r=>routeChoice==='all'||routeChoice===r.vehicleId).map(r=>r.segments.map(seg=>`<polyline points="${seg.nodes.map(id=>nodes[id].x+','+nodes[id].y).join(' ')}" fill="none" stroke="${colors[r.vehicleId]}" stroke-width="3" opacity=".72" ${p?.id!==d().activePlan?.id?'stroke-dasharray="8 5"':''} pointer-events="none"/>`).join('')).join('');
    const dots=s().nodes.map(n=>{const hs=s().households.filter(h=>h.node===n.id&&d().stage[h.id]!=='superseded'),risk=Math.max(0,...hs.map(h=>h.risk)),selected=view==='field'&&form.location===n.id;return `<g class="map-node" role="button" tabindex="0" data-ac="map-node" data-id="${n.id}" aria-label="${esc(n.label)}"><circle cx="${n.x}" cy="${n.y}" r="${n.kind==='junction'?5:selected?13:10}" fill="${n.kind==='shelter'?'#119b8d':risk===3?'#c96b4d':risk===2?'#b39743':'#5575b7'}" stroke="white" stroke-width="3"/><text x="${n.x}" y="${n.y-17}" text-anchor="middle" font-size="13" fill="#344e71">${esc(n.label)}</text>${hs.length?`<text x="${n.x}" y="${n.y+26}" text-anchor="middle" font-size="12" fill="#71829a">${hs.reduce((a,h)=>a+h.people,0)} 人</text>`:''}</g>`;}).join('');
    const positions=s().vehicles.map((v,index)=>{const f=d().fleet[v.id],n=nodes[f.node],dx=f.node==='D'?index*30-28:0;return `<g pointer-events="none" transform="translate(${n.x+dx},${n.y+36})"><rect x="-12" y="-9" width="24" height="18" rx="4" fill="${v.color}"/><text text-anchor="middle" y="4" fill="white" font-size="11">${index+1}</text></g>`;}).join('');
    return `<div class="map-area"><svg viewBox="0 0 830 540" role="group" aria-label="瑞安背景合成演练路网">${lines}${routes}${dots}${positions}</svg></div><p class="map-caption">拓扑示意；点位显示有效转移对象总人数（含已完成），不对应真实行政边界。车辆为最近登记节点，非实时 GPS。</p><div class="map-legend"><span><i></i>转移对象</span><span><i class="shelter"></i>安置点</span><span><i class="blocked"></i>封闭道路</span><span>彩色数字：车辆</span></div>${view==='command'?`<div class="panel-body actions">${btn('全部路线','route','data-id="all"',routeChoice==='all'?'primary small':'small')}${s().vehicles.map(v=>btn(v.name,'route',`data-id="${v.id}"`,routeChoice===v.id?'primary small':'small')).join('')}</div>`:''}`;
  }
  function weatherHTML(){const w=d().weather;return `<section class="panel" id="weather-panel">${head('天气与事件播报','天气为模拟回放；彩云接口已准备，未调用',badge('演练等级 '+w.level))}<div class="panel-body"><div class="close-row"><p><strong style="font-size:1.7rem">${w.rainfall}</strong> mm <span class="muted">/ 演练最近 1 小时累计</span></p><small>${clock(w.updatedAt)}</small></div><p class="muted" style="font-size:.875rem">${esc(w.trigger)}</p><div class="actions no-print">${btn('小幅变化 25 mm','weather','data-id="small"')}${btn('升级情景 60 mm','weather','data-id="strong"')}${btn('升级情景 100 mm','weather','data-id="extreme"')}${btn('恢复初始情景','weather','data-id="normal"')}</div><p class="boundary">以上为演练触发参数，不是官方预警阈值。天气变化仅触发复核，不据此推断积水深度或自动封路。</p><div class="notice" aria-live="polite">${esc(d().lastAnnouncement)}</div><div class="actions no-print">${btn(autoSpeech?'关闭自动播报':'开启自动播报','speech-toggle',`aria-pressed="${autoSpeech}"`)}${btn('播报这条','speech-once')}${btn('停止','speech-stop','','quiet')}<span id="speech-status" class="speech-status">${esc(speechNote)}</span></div></div></section>`;}
  function routeCards(p){return p.routes.filter(r=>r.people||r.holding).map(r=>`<div class="route-card"><div class="close-row"><strong style="color:${s().vehicles.find(v=>v.id===r.vehicleId).color}">${esc(s().vehicles.find(v=>v.id===r.vehicleId).name)}</strong>${badge(r.holding?'原车待协调':r.people+' 人',r.holding?'red':'')}</div><p class="route-line">${esc(nodeName(r.from))} ${r.stops.map(st=>'→ '+esc(homeName(st.id))).join(' ')} ${r.shelterId?'→ '+esc(s().shelters.find(sh=>sh.id===r.shelterId).name):''}</p><small>${r.onboard.length?'已上车保留：'+r.onboard.map(homeName).map(esc).join('、')+'。':''}${r.holding?'没有可行送达路线。':'预计在演练起点后 '+r.finish+' 分钟抵达。'}</small></div>`).join('');}
  function planningHTML(){const p=plan(),b=d().baseline,published=p&&p.id===d().activePlan?.id;return `<section class="panel" id="planning-panel">${head('规划与发布','实际本地求解 · Agent 接口预留',badge(d().activePlan?'已发布 '+d().activePlan.id:'尚未发布',d().activePlan?'teal':'gray'))}<div class="panel-body"><div class="actions">${btn('重新计算草案','generate','','primary')}${d().alternative?btn(showAlternative?'查看主方案':'查看 Plan B','alternative'):''}${btn('查看依据','evidence','','quiet')}</div>${p?`<div class="statusline">${badge(p.id)}<small>输入 v${p.inputVersion} / 执行记录 ${p.executionVersion} · ${p.heuristic?'有界启发式 · 不保证最优':'候选组合搜索'}</small></div><div class="steps">${(d().plan.steps||[]).map((x,i)=>`<span class="${i<3?'done':''}">${esc(published&&i===3?'方案已人工确认发布':x)}</span>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>同一剩余任务快照</th><th>${showAlternative?'备选':'优化'}草案</th><th>规则基线</th></tr></thead><tbody><tr><td>可安排人数</td><td><strong>${p.servedPeople} / ${p.totalPeople}</strong></td><td>${b.servedPeople} / ${b.totalPeople}</td></tr><tr><td>高风险覆盖人数</td><td>${p.urgentPeople}</td><td>${b.urgentPeople}</td></tr><tr><td>需协助对象覆盖人数</td><td>${p.assistedPeople}</td><td>${b.assistedPeople}</td></tr><tr><td>风险加权剩余等待（人·分）</td><td>${p.wait}</td><td>${b.wait}</td></tr><tr><td>最后抵达（起点后）</td><td>${p.servedPeople?p.finish+' 分':'—'}</td><td>${b.servedPeople?b.finish+' 分':'—'}</td></tr><tr><td>车辆行驶总时间</td><td>${p.drive} 分</td><td>${b.drive} 分</td></tr></tbody></table></div><p class="boundary">${JSON.stringify(p.servedIds)===JSON.stringify(b.servedIds)?'两方案覆盖对象相同，可查看覆盖和耗时权衡。':'两方案覆盖对象不同，耗时仅列原始值，不能解释为同批人员提速。'} 基线为模拟规则，不代表瑞安实际部门流程。</p>${differenceHTML(p)}${routeCards(p)}${p.unassigned.length?`<div class="notice warn"><strong>${p.unassigned.reduce((n,h)=>n+h.people,0)} 人待协调</strong>${p.unassigned.map(h=>`<p>${esc(h.name)} · ${h.people} 人：${esc(h.reason)}</p>`).join('')}</div>`:''}<div class="actions no-print">${btn(published?'此方案已发布':showAlternative?'核对并发布备选':'核对并发布草案','confirm',p.servedPeople&&!published?'':'disabled','danger')}</div><p class="boundary">${published?'此方案已发布，可在执行登记中推进。':showAlternative?'备选也是当前约束下的计算结果，可比较后人工采用。':'草案未替换当前发布方案。'} 不向真实车辆或工作人员发送指令。</p>`:`<div class="empty">${d().activePlan?'执行进度已更新。当前发布方案继续保留；如需比较剩余任务，请重新计算。':'等待生成可审核的接送草案。'}</div>`}${d().activePlan?`<details><summary>当前发布方案 ${esc(d().activePlan.id)}</summary><p class="boundary">${clock(d().activePlan.publishedAt)} 人工确认；${esc(d().activePlan.note||'全覆盖草案')}</p>${routeCards(d().activePlan)}</details>`:''}</div></section>`;}
  function assistantHTML(){const q=messages.filter(m=>m.view===view),prompts=view==='field'?['如何填写现场反馈','总结当前情况','查看处理结果']:['总结当前情况','为什么这样安排','生成新草案'];return `<section class="panel assistant-panel" id="ai-assistant" aria-label="AI 对话"><div class="assistant-heading"><span class="ai-emblem" aria-hidden="true">AI</span><div><span class="eyebrow">叫应 · 协同助手</span><h2>与 AI 对话</h2></div>${badge('大模型待接入','gray')}</div><div class="assistant-body"><p class="assistant-intro">${view==='field'?'说清现场情况，协助整理上报内容。':'先问清现场情况，再核对调度方案。'}</p><div class="ai-messages" role="log" aria-live="polite" aria-label="对话记录">${q.length?q.map(m=>`<div class="bubble ${m.role}"><span class="speaker">${m.role==='user'?'你':'协同助手'}</span>${esc(m.text)}${m.action?`<div class="actions">${btn(m.label,'chat-action',`data-id="${m.id}" ${m.revision!==d().revision||voice.active()?'disabled':''}`)}</div>${m.revision!==d().revision?'<small>依据已更新，请重新提问。</small>':''}`:''}</div>`).join(''):`<div class="assistant-welcome"><strong>${view==='field'?'现场有什么变化？':'有什么需要我协助判断？'}</strong><p>${view==='field'?'可以描述道路受阻或新增人员，再带入下方表单核对。':'可以询问待转移人员、方案依据，或让我准备新的调度草案。'}</p></div>`}</div><div class="ai-prompts">${prompts.map((t,i)=>btn(t,'prompt',`data-id="${i}" ${voice.active()?'disabled':''}`,'small')).join('')}</div><div class="ai-composer"><label for="chat-input">${view==='field'?'描述现场情况或提问':'输入问题，开始对话'}</label><textarea id="chat-input" maxlength="2000" ${voice.active()?'readonly':''} placeholder="${view==='field'?'例如：现场新增 2 人，需要陪同接送。':'例如：哪些人还没接到？为什么选择这条路线？'}">${esc(chatDraft)}</textarea><div class="composer-actions">${btn(voice.active()&&voiceTarget==='chat'?(voice.state().phase==='stopping'?'整理中…':'结束识别'):'语音提问','voice',`data-target="chat" aria-pressed="${voice.active()&&voiceTarget==='chat'}" ${!voice.state().supported||voice.state().phase==='stopping'||(voice.active()&&voiceTarget!=='chat')?'disabled':''}`)}${voice.active()&&voiceTarget==='chat'?btn('取消识别','voice-cancel','','quiet'):''}${btn('发送消息 ↗','chat-send',voice.active()?'disabled':'','primary')}</div></div>${voiceTarget==='chat'?`<p class="voice-note" role="status">${esc(voice.state().note)} ${esc(voice.state().preview||'')}</p>`:''}<p class="assistant-mode">当前为本地规则演示，大模型尚未接入；建议需核对后执行。语音识别可能联网。</p></div></section>`;}
  function reportsHTML(){return `<section class="panel" id="reports-panel">${head(view==='field'?'我的演练反馈与处理结果':'现场反馈待办','两端共享同一份记录',badge(d().reports.length+' 条'))}${d().reports.length?d().reports.map(r=>`<article class="report-card"><header><strong>${esc(r.id)} · ${reportNames[r.kind]}</strong>${badge(statusNames[r.status],r.status==='pending'?'red':r.status==='resolved'?'teal':'')}</header><p>${esc(locName(r.location))}${r.people?' · 新增 '+r.people+' 人':''}</p><p>${esc(r.text)}</p><small>${esc(r.reporter)} · ${clock(r.createdAt)}</small>${r.note?`<p>核实说明：${esc(r.note)}</p>`:''}${r.resolution?`<p>处理结果：${esc(r.resolution)}</p>`:''}${view==='command'?`<div class="actions" style="margin-top:10px">${r.status==='pending'?btn('核实并处理','review',`data-id="${r.id}"`,'primary small'):['accepted','coordination'].includes(r.status)?btn(r.kind==='road'?'登记障碍排除':'登记处理结果','resolve',`data-id="${r.id}"`,'small'):''}</div>`:''}</article>`).join(''):'<div class="empty">尚无反馈。可在现场表单选择位置，或切换到“调度演练路网”选点上报。</div>'}</section>`;}
  function executionHTML(){return `<div class="panel-body"><div class="actions">${btn('登记已联系全部家庭 / 接送组','contact-all',s().households.some(h=>d().stage[h.id]==='waiting'&&!d().contacts[h.id]?.contacted)?'':'disabled')}${d().phase==='preparation'?btn('开始模拟执行','start',d().activePlan?'':'disabled','primary'):badge('按站点登记推进','teal')}</div><p class="boundary">联系登记不代表上车或到达。车辆每次推进到下一接人点；接完本车人员后登记到达，再人工核验。</p><div class="execution-grid">${s().vehicles.map(v=>{const f=d().fleet[v.id],r=d().activePlan?.routes.find(r=>r.vehicleId===v.id),st=r?.stops.find(st=>d().stage[st.id]==='waiting'),blocked=state.blockedVehicles.includes(v.id);return `<div class="route-card"><header class="close-row"><strong>${esc(v.name)}</strong>${badge(f.finished?'本趟已到达':blocked&&r?.people?'路线或批次待复核':f.onboard.length?'接送中':'待执行',blocked&&r?.people?'red':'')}</header><p>登记位置：${esc(nodeName(f.node))} · 起点后 ${f.minute} 分 · 车上 ${f.onboard.reduce((n,id)=>n+s().households.find(h=>h.id===id).people,0)} 人</p><div class="actions">${btn(st?'登记接到 '+esc(homeName(st.id)):'登记到达安置点','step',`data-id="${v.id}" ${d().phase!=='executing'||!r?.people||f.finished||blocked?'disabled':''}`,'small')}</div></div>`;}).join('')}</div><div class="table-wrap"><table><thead><tr><th>家庭 / 接送组</th><th>人数</th><th>联系</th><th>执行记录</th><th>核验</th></tr></thead><tbody>${s().households.filter(h=>d().stage[h.id]!=='superseded').map(h=>`<tr><td>${esc(h.name)}</td><td>${h.people}</td><td>${d().contacts[h.id]?.contacted?'已联系':'待联系'}</td><td>${stageNames[d().stage[h.id]]}</td><td>${d().stage[h.id]==='arrived'?btn('人工核验','verify',`data-id="${h.id}"`,'small'):'—'}</td></tr>`).join('')}</tbody></table></div></div>`;}
  function ledgerHTML(){return `<div class="panel-body"><p class="boundary">全部为合成演练资料。执行中新增需求请走现场反馈，避免追溯修改已上车人数。</p><div class="table-wrap"><table><thead><tr><th>家庭 / 接送组</th><th>人数</th><th>演练风险</th><th>需求</th><th></th></tr></thead><tbody>${s().households.filter(h=>d().stage[h.id]!=='superseded').map(h=>`<tr><td>${esc(h.name)}</td><td>${h.people}</td><td>${h.risk} 级</td><td>${h.wheelchair?'轮椅位':h.assistance?'需协助':'常规'}</td><td>${btn('编辑','edit',`data-kind="households" data-id="${h.id}" ${d().phase!=='preparation'||h.sourceBatchId?'disabled':''}`,'small')}${h.sourceBatchId?'<small>请通过村级更正</small>':''}</td></tr>`).join('')}</tbody></table></div>${['vehicles','shelters'].map(kind=>`<h3 style="font-size:1rem">${kind==='vehicles'?'车辆':'安置点'}</h3><div class="table-wrap"><table><thead><tr><th>名称</th><th>容量</th><th>状态</th><th></th></tr></thead><tbody>${s()[kind].map(x=>`<tr><td>${esc(x.name)}</td><td>${x.capacity}${kind==='vehicles'?(x.wheelchair?'，含 1 轮椅位':'，无轮椅位'):'，已占 '+d().occupancy[x.id]}</td><td>${x.available?'可用':'停用'}</td><td>${btn('编辑','edit',`data-kind="${kind}" data-id="${x.id}" ${d().phase!=='preparation'?'disabled':''}`,'small')}</td></tr>`).join('')}</tbody></table></div>`).join('')}</div>`;}
  function evidenceHTML(){return `<div class="panel-body"><p><strong>规则基线</strong>：按演练风险从高到低、协助需求、编号排序；在可行车辆与安置点中，先选距该户最近的安置点，再选最早到户的车辆。已选安置点保持固定。两种方法遵守相同的座位、轮椅位、安置容量和开放道路约束。</p><p><strong>优化顺序</strong>：先保障已上车人员的可行送达，再比较高风险人数、需协助人数、覆盖总人数，之后比较加权等待、最后抵达和行驶总时间。等待权重为演练设定：高风险 3、需协助 2、其他 1。</p><p><strong>范围</strong>：单车单趟。最多 8 个待接组时使用候选组合搜索；更多组使用有界多起点启发式插入，不保证全局最优。村级上报经核实后按同行关系成组，未补齐信息的人数列为待协调。已完成任务锁定，已上车人员留原车。</p><p><strong>触发</strong>：模拟天气等级跨级、核实道路受阻、核实新增人员或人工编辑时生成草案。同级天气变化保持方案。生成草案不自动替换发布方案。</p><p><strong>依据状态</strong>：尚未接入公开预案知识库。当前规则来自演练设计，不是瑞安官方预案条款。模型 ${esc((d().plan||d().activePlan)?.algorithm||d().algorithm)}；基线 risk-nearest-feasible-3.0；Agent、彩云和 GPS 均未连接。</p><p class="boundary">地域名称依据：<a href="https://www.razx.gov.cn/web/pc/news/show.do?id=4002" target="_blank" rel="noreferrer">瑞安官方沿革</a>。天气接口依据：<a href="https://docs.caiyunapp.com/weather-api/v2/v2.6/6-weather.html" target="_blank" rel="noreferrer">彩云 v2.6 文档</a>。真实地图采用公开地理数据；调度演练路网、人员和风险为合成数据。</p></div><div class="event-list">${d().log.slice(0,25).map(x=>`<div class="event"><time>${clock(x.time)}</time>${esc(x.message)}</div>`).join('')}</div>`;}
  function reportHTML(){const p=d().plan||d().activePlan;return `<div class="panel-body"><h2>瑞安合成演练决策报告</h2><p>生成时间：${new Date().toLocaleString('zh-CN')}。输入 v${d().inputVersion}；执行记录 ${d().executionVersion}。</p><p>数据性质：合成演练；当前 ${d().weather.rainfall} mm 为模拟最近一小时累计，非实时天气。Agent 和彩云未接入。</p><p>当前草案：${d().plan?.id||'无'}；当前发布方案：${d().activePlan?.id||'未发布'}。二者可能不同，确认记录以发布方案为准。</p>${p?routeCards(p):'<p>没有可导出的方案。</p>'}${p?.unassigned.length?`<p>待协调：${p.unassigned.map(h=>esc(h.name)+' '+h.people+' 人').join('；')}</p>`:''}${deltaHTML()}<p>本次总人数 ${state.metrics.people}；已人工核验 ${state.metrics.verified}；车上 ${state.metrics.boarded}；到达待核验 ${state.metrics.arrived}。</p>${d().baseline?`<p>同快照规则基线 ${d().baseline.servedPeople} 人；优化草案 ${d().plan.servedPeople} 人。${JSON.stringify(d().plan.servedIds)===JSON.stringify(d().baseline.servedIds)?'覆盖对象相同。':'覆盖对象不同，不据此声称同批人员提速。'}</p>`:''}<p>算法：${esc((d().plan||d().activePlan)?.algorithm||d().algorithm)}。不预测单点水深，不发送真实调度指令。详细输入、两方案及日志可另存 JSON。</p><div class="actions no-print">${btn('打印 / 保存 PDF','print','','primary')}${btn('导出完整演练 JSON','export')}</div><h3>确认与事件记录</h3>${d().log.map(x=>`<p style="font-size:.875rem">${clock(x.time)}　${esc(x.message)}</p>`).join('')}</div>`;}
  function detailsHTML(){return `<section class="panel no-print" id="task-panel">${head('任务与依据')}<div class="tabs" role="tablist">${[['execution','任务进展'],['ledger','人员资源'],['evidence','事件与依据'],['report','决策报告']].map(([id,label])=>btn(label,'tab',`data-id="${id}" role="tab" aria-selected="${tab===id}"`,tab===id?'active':'')).join('')}</div>${({execution:executionHTML,ledger:ledgerHTML,evidence:evidenceHTML,report:reportHTML}[tab])()}</section>`;}
  function fieldFormHTML(){const places=form.kind==='road'?s().edges.map(e=>({id:e.id,label:roadName(e.id)})):s().nodes;return `<section class="panel" id="manual-field-panel">${head('手动填写现场反馈','也可使用上方语音助手；填写后统一核对确认')}<form id="field-form" class="panel-body"><div class="form-grid"><div class="field"><label for="report-kind">反馈类型</label><select id="report-kind">${Object.entries(reportNames).map(([id,t])=>`<option value="${id}" ${form.kind===id?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="report-location">关联位置</label><select id="report-location" required><option value="">请选择已核实的演练位置</option>${places.map(n=>`<option value="${n.id}" ${form.location===n.id?'selected':''}>${esc(n.label)}</option>`).join('')}</select></div>${form.kind==='people'?`<div class="field"><label for="report-people">新增人数（含同行者）</label><input id="report-people" type="number" min="1" max="30" value="${form.people}" required></div><div class="field"><label>协助需求</label><label class="check"><input id="report-assistance" type="checkbox" ${form.assistance?'checked':''}>需要协助</label><label class="check"><input id="report-wheelchair" type="checkbox" ${form.wheelchair?'checked':''}>需要 1 个轮椅位</label></div>`:''}<div class="field full"><label for="report-text">现场说明</label><textarea id="report-text" maxlength="2000" required ${voice.active()?'readonly':''} placeholder="例如：演练东桥有倒树，车辆无法通行。">${esc(form.text)}</textarea>${voiceHTML('report')}<div class="actions">${btn('整理字段建议','parse-report',voice.active()?'disabled':'')}${btn('填入演练示例','sample',voice.active()?'disabled':'','quiet')}</div></div><div class="field full"><label for="reporter">演练上报人</label><input id="reporter" maxlength="40" value="${esc(form.reporter)}" required></div></div><div class="actions" style="margin-top:15px"><button type="submit" class="primary" ${busy||voice.active()||!connected?'disabled':''}>生成待确认反馈</button></div><p class="boundary">提交后进入待核实。自由文本和语音不会直接封路、发布方案或确认安全。</p></form></section>`;}
  function updateAiLauncher(){const launcher=document.querySelector('.ai-floating'),composer=document.querySelector(view==='field'?(fieldWorkspace==='village'?'.village-voice-box':'.field-voice-composer'):'.ai-composer');if(!launcher||!composer)return;const r=composer.getBoundingClientRect();launcher.classList.toggle('is-visible',r.bottom<60||r.top>innerHeight-70);}
  function render(){
    if(!$('content'))return;const focus=document.activeElement,focusId=focus?.id,selection=focus&&['textarea','text','number'].includes(focus.type)?[focus.selectionStart,focus.selectionEnd]:null,scrollY=window.scrollY,chatScroll=document.querySelector('.ai-messages')?.scrollTop;
    document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    if(!state&&pagesMode){$('content').innerHTML=`<section class="panel"><div class="panel-body"><h1>叫应 AI · 浏览器演练</h1><h2>${window.JiaoyingPages.lastError?'浏览器存储暂不可用':'正在准备演练'}</h2><p>${esc(window.JiaoyingPages.lastError||'正在读取此浏览器的演练；首次访问会创建全新的合成场景。')}</p><p>无需启动本机服务。同一浏览器的两端可联动，不同设备不共享数据。仅在写入成功后显示提交成功。</p>${btn('重新连接','retry')}<a class="button" href="start.html">返回网页入口</a></div></section>`;return;}
    if(!state){$('content').innerHTML=`<div class="page-title"><div><span class="eyebrow">JIAOYING / LOCAL</span><h1>瑞安协同演练</h1></div></div><section class="panel"><div class="panel-body"><h2>${connected?'正在载入演练':'需要启动本地演练服务'}</h2><p>请双击项目根目录的“打开叫应AI网页.cmd”（或 demo 文件夹中的“启动V3.4演示.cmd”），再进入下面的新地址。两个网页共享同一场演练。</p><p class="boundary">V3 不直接以文件方式运行。公网版本仍是此前的 V2.2，本轮未发布。</p>${btn('重新连接','retry')}<div class="actions" style="margin-top:14px"><a class="button primary" href="http://127.0.0.1:8767/#command">新版指挥台 ↗</a><a class="button" href="http://127.0.0.1:8767/#field">新版现场端 ↗</a><a class="button quiet" href="http://127.0.0.1:8767/start.html">网页入口与会议清单</a></div></div></section>`;return;}
    $('content').innerHTML=titleHTML()+fieldUpdateHTML()+metricHTML()+deltaHTML()+(view==='command'?`<div class="workspace overview"><div>${mapHTML()}</div><div>${assistantHTML()}</div></div>${villageLedgerHTML()}${fieldLiveHTML()}<div class="workspace operations village-command-workspace"><div>${villageReportsHTML()}${reportsHTML()}${weatherHTML()}</div><div>${planningHTML()}</div></div>${detailsHTML()}`:`<div class="field-workspace-tabs" role="group" aria-label="现场业务模块">${btn("村级人数上报","field-workspace",'data-id="village" aria-pressed="'+(fieldWorkspace==='village')+'"',fieldWorkspace==='village'?'active':'')}${btn("任务与异常反馈","field-workspace",'data-id="tasks" aria-pressed="'+(fieldWorkspace==='tasks')+'"',fieldWorkspace==='tasks'?'active':'')}</div>${fieldWorkspace==='village'?`<div class="field-layout"><div>${villageComposerHTML()}</div><div>${villagePreviewHTML()}</div></div>${villageLedgerHTML()}${villageReportsHTML()}`:`<div class="field-flow"><span>01 选择当前任务</span><i>→</i><span>02 快捷点击 / 语音整理</span><i>→</i><span>03 人工确认，即时联动</span></div><div class="field-layout"><div>${fieldTasksHTML()}${fieldAgentHTML()}${fieldFormHTML()}<details class="field-general-chat"><summary>通用对话与方案解释</summary>${assistantHTML()}</details></div><div>${fieldPreviewHTML()}${reportsHTML()}${mapHTML()}</div></div>`}`)+`<button class="ai-floating no-print" data-ac="focus-ai" aria-label="打开 AI 对话"><b>${view==='field'?'声':'AI'}</b><span>${view==='field'?'语音协同助手':'与 AI 对话'}</span>↗</button><p class="boundary">${pagesMode?'GitHub 浏览器原型':'本地独立原型'} · 真实底图 + 合成业务演练 · 尚未接入原“叫应” · 风险等级为演练设定，不预测单点积水深度。${pagesMode?'记录保存在此浏览器，不同设备不共享；清除站点数据会删除记录，重要记录请导出。':'重启服务会重置，重要记录请导出。'}</p>`;
    $('content').setAttribute('aria-busy',String(busy));if(busy)document.querySelectorAll('.field-layout input,.field-layout textarea,.field-layout select').forEach(el=>el.disabled=true);window.JiaoyingMotion?.refresh();
    if($('geographic-map'))window.RuianMap?.mount($('geographic-map'));
    if(focusId&&$(focusId)&&!$(focusId).disabled){$(focusId).focus({preventScroll:true});if(selection&&selection[0]!==null)try{$(focusId).setSelectionRange(...selection);}catch(_){}}
    if(chatScroll!==undefined&&document.querySelector('.ai-messages'))document.querySelector('.ai-messages').scrollTop=chatScroll;
    window.scrollTo(0,scrollY);updateAiLauncher();document.title=(view==='field'?'现场反馈':'指挥工作台')+' · 叫应 AI 瑞安演练';
  }
  function openModal(kind,id,extra){modal={kind,id,extra,revision:d().revision,session:state.session};let content='';
    if(kind==='confirm'){const p=plan();modal.alternative=showAlternative;content=`<h2>核对并模拟发布 ${esc(p.id)}</h2><p>本次可安排 ${p.servedPeople} / ${p.totalPeople} 人，${p.unassigned.length} 个组或批次待协调。</p><p>已上车人员保持原车，已完成任务不重新安排。本操作替换未完成任务的发布方案。</p>${p.unassigned.length?'<label for="modal-note">未安排人员协调措施（至少 5 字）</label><textarea id="modal-note" required maxlength="300"></textarea>':'<input id="modal-note" type="hidden" value="全覆盖草案经人工核对">'}<label class="check"><input id="modal-check" type="checkbox" required>我已核对当前草案、路线和未安排人员。</label><button type="submit" class="danger">确认并模拟发布</button>`;}
    else if(kind==='review'||kind==='resolve'){const r=d().reports.find(r=>r.id===id);content=`<h2>${kind==='review'?'核实反馈':'登记处理结果'} ${esc(id)}</h2><p>${esc(locName(r.location))} · ${reportNames[r.kind]}</p><div class="notice">${esc(r.text)}</div>${kind==='review'?'<label for="review-decision">核实结论</label><select id="review-decision"><option value="accept">采纳并进入对应处理流程</option><option value="reject">不采纳</option></select>':''}<label for="modal-note">${kind==='review'?'核实说明':'处理结果'}</label><textarea id="modal-note" maxlength="300" required></textarea>${kind==='resolve'&&r.kind==='road'?'<label class="check"><input id="modal-check" type="checkbox" required>本条反馈对应的障碍已经核实排除；其他未解决反馈仍会阻止道路开放。</label>':''}<p class="boundary">${kind==='review'?'道路或人数反馈采纳后会更新输入并生成草案；不会自动发布。':'处理结果会同步到现场网页。'}</p><button type="submit" class="primary">保存核实结果</button>`;}
    else if(kind==='village-review'||kind==='village-complete'){content=JiaoyingVillageUI.review(state,id,kind);}
    else if(kind==='edit'){const item=s()[extra].find(x=>x.id===id);content=`<h2>编辑 ${esc(item.name)}</h2>${extra==='households'?`<label for="edit-people">人数</label><input id="edit-people" type="number" min="1" max="30" value="${item.people}" required><label for="edit-risk">演练风险等级</label><select id="edit-risk">${[1,2,3].map(x=>`<option ${x===item.risk?'selected':''}>${x}</option>`).join('')}</select><label class="check"><input id="edit-assistance" type="checkbox" ${item.assistance?'checked':''}>需要协助</label><label class="check"><input id="edit-wheelchair" type="checkbox" ${item.wheelchair?'checked':''}>需要轮椅位</label>`:`<label for="edit-capacity">容量</label><input id="edit-capacity" type="number" min="0" max="100" value="${item.capacity}" required><label class="check"><input id="edit-available" type="checkbox" ${item.available?'checked':''}>可用</label>${extra==='vehicles'?`<label class="check"><input id="edit-wheelchair" type="checkbox" ${item.wheelchair?'checked':''}>包含 1 个轮椅位</label>`:''}`}<p class="boundary">保存后按新条件生成草案，原发布记录保留。</p><button type="submit" class="primary">保存并重新计算</button>`;}
    else if(kind==='settings'){content=`<h2>接口与演练范围</h2><p><strong>语音协同助手</strong>：已接入浏览器语音识别，本地规则将原话整理为任务或反馈草稿；均需人工确认。DeepSeek 大模型接口仍待接入。</p><p><strong>彩云天气</strong>：已准备 v2.6 查询模板与单位校验，当前不调用。经纬度尚待选定真实点位后配置。</p><p><strong>地图</strong>：首页使用本地保存的 OpenStreetMap 瑞安市城区真实道路与水系；合成调度路网独立显示，尚未据此计算真实导航路线。</p><p><strong>两端同步</strong>：${pagesMode?'同一浏览器、同一站点的两个标签页，通过浏览器存储与消息通知同步，轮询作为后备。不同浏览器、隐私窗口或设备不共享演练；刷新可读取本浏览器已保存状态，清除站点数据会删除记录。':'同一台电脑的两个网页通过本机服务即时推送，断线时保留轮询后备；不是公网服务，当前不开放其他设备接入。刷新网页保留服务内状态，服务重启会重置。'}</p><p><strong>语音播报</strong>：由浏览器语音合成；需手动开启自动播报或点击单条播报。声音可用性取决于浏览器。</p><p><strong>业务范围</strong>：村级增报、总数观测、更正与待补信息台账；支持最多 500 名有效人员、200 个有效接送组。单车单趟，容量不足明确待协调；核实封路或新增人员后生成剩余任务草案。</p><p class="boundary">没有真实定位、真实灾情或单点积水深度预测。不发送真实消息。${pagesMode?'本页面是 GitHub 浏览器演示，各访客独立演练；业务内容不上传 GitHub。':'本轮未更新 GitHub 公网版本。'}</p><div class="actions">${btn('导出完整记录','export')}${btn('重置这场演练','reset-dialog','','danger')}</div>`;}
    else if(kind==='reset'){content='<h2>重置本地演练</h2><p>两个网页将同时恢复初始数据。需要保留的记录请先导出 JSON。</p><label class="check"><input id="modal-check" type="checkbox" required>我已保存需要的记录，重置这场合成演练。</label><button type="submit" class="danger">确认重置</button>';}
    else if(kind==='map'){const isRoad=s().edges.some(e=>e.id===id);content=`<h2>${esc(locName(id))}</h2><p>${isRoad?'道路状态：'+(s().edges.find(e=>e.id===id).open?'开放':'已确认封闭'):'演练点位，可关联现场反馈。'}</p><p class="boundary">地图为合成路网，位置不是现实地理坐标。</p>${btn('在此位置上报','report-at',`data-id="${id}" data-kind="${isRoad?'road':'people'}"`,'primary')}`;}
    $('dialog-content').innerHTML=`<form id="modal-form" class="dialog-body"><div class="close-row"><span class="eyebrow">JIAOYING / REVIEW</span><button type="button" data-ac="close">关闭</button></div>${content}<p id="modal-error" role="alert" style="color:#ae463a"></p></form>`;if(!$('dialog').open)$('dialog').showModal();if($('vreview-people'))$('vreview-people').readOnly=true;
  }
  async function sendChat(){
    if(voice.active())throw new Error('请先结束语音，核对后发送');const t=chatDraft.trim();if(!t)return;messages.push({view,role:'user',text:t});chatDraft='';let reply='',ac=null,label='';const p=d().plan||d().activePlan;
    if(view==='field'&&/处理结果|反馈结果|反馈进度|查看.*记录/.test(t)){reply=`已有 ${d().reports.length} 条反馈，其中 ${state.metrics.pendingReports} 条待核实。处理状态和核实说明显示在反馈列表中。`;ac='show-reports';label='查看反馈处理列表';}
    else if(view==='field'&&/如何|怎么|填写/.test(t)&&/反馈|上报/.test(t)){reply='先选择反馈类型与位置，再填写事实、人数及协助需求。核对后提交，指挥端核实处理。可以在表单中语音输入。';ac='open-report';label='填写现场反馈';}
    else if(view==='field'&&/上报|新增|倒树|倒伏|受阻|无法通行|反馈/.test(t)){reply='可以把这段话带入现场表单，再核对事件类型、关联位置、人数和协助需求后提交。文字描述不会直接更改路况或确认安全。';ac='fill-report';label='带入上报表单';}
    else if(/生成|重算|重新规划/.test(t)){reply='可以按当前输入和车辆登记位置重新计算。新结果是草案，尚未替换发布方案。';ac='generate';label='计算当前草案';}
    else if(/为什么|依据|基线/.test(t)){reply='当前使用真实运行的约束搜索：保留已上车人员，检查开放道路、座位、轮椅位与安置容量；规则基线则按风险优先、近点分配。没有连接预案知识库。';ac='evidence';label='查看计算规则与依据';}
    else if(/备用|备选|plan\s*b/i.test(t)){reply=d().alternative?'已有同一快照下的备选草案，可查看并人工选择。':'当前没有备选草案，请先重新计算。';ac=d().alternative?'alternative':'generate';label=d().alternative?'查看 Plan B':'生成候选草案';}
    else if(/天气|彩云|模型|agent|deepseek/i.test(t)){reply='Agent 和彩云天气均只准备接口，当前没有调用外部服务。雨量是带明确时间窗的模拟输入，不直接推断积水深度。';ac='settings';label='查看接口状态';}
    else if(/总结|情况|谁|缺口|安排/.test(t)){reply=`当前共 ${state.metrics.people} 人，待接 ${state.metrics.waiting} 人、车上 ${state.metrics.boarded} 人、到达待核验 ${state.metrics.arrived} 人、已核验 ${state.metrics.verified} 人。\n${p?`参考${d().plan?'草案':'已发布方案'} ${p.id}，该快照安排 ${p.servedPeople} 人。`:'尚未生成方案。'}\n待核实反馈 ${state.metrics.pendingReports} 条。`;}
    else {reply='当前是有限规则导览，尚不能可靠理解这条自由表达。可询问“总结当前情况”“为什么这样安排”，或到现场反馈网页填写并核对事件。此次没有更改路况或方案。';}
    messages.push({view,role:'assistant',text:reply,id:String(messages.length+1),action:ac,label,sourceText:t,revision:d().revision});render();highlightResult('ai-assistant');const log=document.querySelector('.ai-messages');if(log){log.scrollTop=log.scrollHeight;log.scrollIntoView({block:'nearest',behavior:'smooth'});}
  }
  function parseReport(){
    if(voice.active())throw new Error('请先结束语音识别');invalidateFieldDraft();
    const result=JiaoyingFieldAssistant.prepare(form.text,{data:d(),vehicleId:fieldVehicle,householdId:fieldHousehold,location:form.location,reporter:form.reporter});
    if(result.proposal){result.proposal.payload.source=form.voiceFilled?'voice':'manual';if(result.proposal.action==='report'){const p=result.proposal.payload;form.kind=p.kind;form.location=p.location;form.people=p.people||'';form.wheelchair=p.wheelchair===true;form.assistance=p.assistance===true;}}
    displayPrepared(result,'manual');
  }
  function exportJSON(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),dataNature:'业务为合成演练；真实地理底图来源 OpenStreetMap，详见 assets/maps/SOURCES.md',...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='叫应AI-瑞安演练-v'+d().inputVersion+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function villageUIState(){return {form:villageForm,prepared:villagePrepared,receipt:villageReceipt,filter:villageFilter,view,voiceActive:voice.active(),connected:connected&&!!state.capabilities?.villageReporting};}
  const villageHelpers={head,btn,badge,voiceHTML};
  function villageComposerHTML(){return window.JiaoyingVillageUI?JiaoyingVillageUI.composer(state,villageUIState(),villageHelpers):'';}
  function villagePreviewHTML(){return window.JiaoyingVillageUI?JiaoyingVillageUI.preview(state,villageUIState(),villageHelpers):'';}
  function villageLedgerHTML(){return window.JiaoyingVillageUI&&state.capabilities?.villageReporting?JiaoyingVillageUI.ledger(state,villageUIState(),villageHelpers):'';}
  function villageReportsHTML(){return window.JiaoyingVillageUI&&state.capabilities?.villageReporting?JiaoyingVillageUI.reports(state,villageUIState(),villageHelpers):'';}
  const nullableNumber=value=>value===null||value===undefined||value===''?null:Number(value);
  function invalidateVillage(){villagePrepared=null;if($('village-preview'))$('village-preview').querySelector('.panel-body').textContent='输入已变化，请重新整理确认卡。';}
  function setVillagePrepared(result,focus=true){villagePrepared={...result,revision:d().revision,session:state.session,requestId:crypto.randomUUID()};if(focus){render();$('village-preview')?.scrollIntoView({block:'start'});highlightResult('village-preview');}}
  function prepareVillage(focus=true){if(!state||!window.JiaoyingVillageAssistant)return;setVillagePrepared(JiaoyingVillageAssistant.prepare(villageForm.text,{data:d(),...villageForm,reporter:form.reporter}),focus);}
  function refreshVillageControls(){const p=villagePrepared?.proposal?.payload;if(!p)return;const stale=villagePrepared.session!==state.session||villagePrepared.revision!==d().revision,dup=JiaoyingVillageUI.duplicate(d(),p);if($('village-draft-state'))$('village-draft-state').innerHTML=JiaoyingVillageUI.draftState(d(),p,villageHelpers);if($('village-duplicate'))$('village-duplicate').innerHTML=JiaoyingVillageUI.duplicateHTML(d(),p,villageHelpers);const b=document.querySelector('[data-ac="village-submit"]');if(b){b.textContent=JiaoyingVillageUI.submitLabel(p);b.disabled=busy||!connected||!state.capabilities?.villageReporting||voice.active()||stale||!!dup&&!p.duplicateAcknowledged;}}
  function validateVillagePayload(p){
    if(!d().villages?.some(v=>v.id===p.villageId))throw new Error('请先选择演示村庄');
    if(p.people===''||p.people===null||!Number.isInteger(Number(p.people))||Number(p.people)<(p.mode==='increment'?1:0)||Number(p.people)>500)throw new Error('请填写有效总人数，新增 1–500 人，观测或更正 0–500 人');
    p.people=Number(p.people);p.assistancePeople=nullableNumber(p.assistancePeople);p.wheelchairPeople=nullableNumber(p.wheelchairPeople);
    for(const [label,n] of [['协助人数',p.assistancePeople],['轮椅人数',p.wheelchairPeople]])if(n!==null&&(!Number.isInteger(n)||n<0||n>p.people))throw new Error(label+'须为不超过总人数的非负整数');
    if(p.wheelchairPeople!==null&&p.assistancePeople!==null&&p.wheelchairPeople>p.assistancePeople)throw new Error('轮椅人数应包含在协助人数内');
    if(!p.reporter?.trim())throw new Error('请填写上报人');
    if(p.mode==='correction'&&!p.targetId)throw new Error('请选择要更正的原批次');
    if(p.mode==='snapshot'&&!Number.isFinite(Date.parse(p.observedAt)))throw new Error('总数观测必须填写人数清点时间');
    if(!p.text?.trim())p.text=`手动填写：${p.mode==='increment'?'本批新增':p.mode==='snapshot'?'当前待转移总数':'更正批次人数'} ${p.people} 人。`;
  }
  async function villageClick(ac,id){
    if(voice.active())throw new Error('请先结束语音识别，再核对确认卡');
    if(ac==='village-ledger'){$('village-ledger')?.scrollIntoView({block:'start'});highlightResult('village-ledger');return;}
    if(ac==='village-prepare'){prepareVillage();return;}
    if(ac==='village-manual'){
      if(!villageForm.villageId)throw new Error('请先选择上报村庄');
      const original=d().villageReports?.find(r=>r.id===villageForm.targetId);
      setVillagePrepared({proposal:{action:'village-report',payload:{villageId:villageForm.villageId,pickupId:villageForm.pickupId,mode:villageForm.mode,targetId:villageForm.targetId,people:'',assistancePeople:null,wheelchairPeople:null,groupPolicy:'unknown',observedAt:villageForm.observedAt,scope:'waiting',text:villageForm.text,reporter:form.reporter,source:'manual',duplicateAcknowledged:false,...(villageForm.mode==='correction'&&original?{people:original.people,pickupId:original.pickupId,assistancePeople:original.assistancePeople,wheelchairPeople:original.wheelchairPeople,groupPolicy:original.groupPolicy}:{})}},warnings:[],evidence:['手动填写，未调用大模型']});return;
    }
    if(ac==='village-example'){if(!villageForm.villageId)villageForm.villageId=d().villages?.[0]?.id||'';villageForm.text=villageForm.mode==='snapshot'?'当前还有20人等待转移。':villageForm.mode==='correction'?'更正为18人，其中3人需要协助，包含1名轮椅人员。都是独立人员，可以分组。':'新增20人，其中3人需要协助，包含1名轮椅人员。都是独立人员，可以分组。';villageForm.source='text';villagePrepared=null;render();$('village-utterance')?.focus({preventScroll:true});return;}
    if(ac==='village-clear'){villagePrepared=null;villageForm.text='';villageReceipt='';render();return;}
    if(ac==='village-duplicate'){if(villagePrepared?.proposal){villagePrepared.proposal.payload.duplicateAcknowledged=true;villagePrepared.requestId=crypto.randomUUID();render();}return;}
    if(ac==='village-refresh'){if(!villagePrepared)return;villagePrepared={...villagePrepared,revision:d().revision,session:state.session,requestId:crypto.randomUUID()};render();return;}
    if(ac==='village-review'||ac==='village-complete'){openModal(ac,id);return;}
    if(ac==='village-correct'){const r=d().villageReports.find(x=>x.id===id);if(!r)return;Object.assign(villageForm,{villageId:r.villageId,pickupId:r.pickupId,mode:'correction',targetId:id,text:'',source:'text'});villagePrepared=null;render();$('village-composer')?.scrollIntoView({block:'start'});return;}
    if(ac==='village-submit'){
      const prepared=villagePrepared;if(!prepared?.proposal)throw new Error('请先整理确认卡');
      if(!state.capabilities?.villageReporting)throw new Error(pagesMode?'浏览器演练尚未就绪，请重新连接':'请启动 V3.4 本地服务');
      if(prepared.revision!==d().revision||prepared.session!==state.session)throw new Error('现场记录已更新，请核对后更新确认卡依据');
      const payload={...prepared.proposal.payload};validateVillagePayload(payload);
      if(JiaoyingVillageUI.duplicate(d(),payload)&&!payload.duplicateAcknowledged)throw new Error('请先核实是否与近期上报属于同一批人员');
      const result=await action('village-report',payload,prepared.revision,prepared.session,prepared.requestId);
      const r=result.data.villageReports?.[0];villageReceipt=`${r?.id||'村级上报'} · ${payload.people} 人已提交，待指挥台核实。`;
      if(villagePrepared===prepared){villagePrepared=null;villageForm.text='';villageForm.source='text';}
      render();notify(villageReceipt);$('village-reports')?.scrollIntoView({block:'start'});highlightResult('village-reports');
    }
  }
  document.addEventListener('input',e=>{const id=e.target.id;if(id==='village-utterance'){villageForm.text=e.target.value;villageForm.source='text';invalidateVillage();}if(e.target.dataset?.vdraft&&villagePrepared?.proposal){const key=e.target.dataset.vdraft;villagePrepared.proposal.payload[key]=e.target.value;villagePrepared.proposal.payload.duplicateAcknowledged=false;villagePrepared.requestId=crypto.randomUUID();refreshVillageControls();}if(id==='village-reporter'&&villagePrepared?.proposal){villagePrepared.proposal.payload.reporter=e.target.value;villagePrepared.requestId=crypto.randomUUID();}});
  document.addEventListener('change',e=>{const id=e.target.id,map={'village-id':'villageId','village-mode':'mode','village-pickup':'pickupId','village-target':'targetId','village-observed':'observedAt'};if(map[id]){villageForm[map[id]]=e.target.value;if(id==='village-id'){villageForm.pickupId='';villageForm.targetId='';}invalidateVillage();render();}if(id==='village-filter'){villageFilter=e.target.value;render();}});

  function invalidateFieldDraft(){const had=!!fieldPrepared;fieldPrepared=null;fieldConfirmed=false;if(had&&$('field-preview'))$('field-preview').querySelector('.panel-body').textContent='输入或现场对象已变化，请重新整理并核对。';}
  document.addEventListener('input',e=>{const id=e.target.id,v=e.target.value;if(id==='field-utterance'){fieldUtterance=v;fieldSource='text';invalidateFieldDraft();}if(id==='field-reporter'){form.reporter=v;fieldConfirmed=false;if($('field-confirm-check'))$('field-confirm-check').checked=false;}if(['report-text','report-people','reporter'].includes(id))invalidateFieldDraft();if(id==='chat-input')chatDraft=v;if(id==='report-text'){form.text=v;form.checked=false;form.voiceFilled=false;}if(id==='reporter')form.reporter=v;if(id==='report-people'){form.people=Number(v);form.checked=false;}if(['report-text','report-people','reporter'].includes(id)&&$('report-checked')){form.checked=false;$('report-checked').checked=false;}});
  document.addEventListener('change',e=>{const id=e.target.id;if(id==='field-confirm-check'){fieldConfirmed=e.target.checked;return;}if(['report-kind','report-location','report-assistance','report-wheelchair'].includes(id))invalidateFieldDraft();if(['field-vehicle','field-household','field-location'].includes(id)){if(id==='field-vehicle'){fieldVehicle=e.target.value;fieldHousehold='';fieldLocation='';}if(id==='field-household')fieldHousehold=e.target.value;if(id==='field-location')fieldLocation=e.target.value;invalidateFieldDraft();render();}});
  document.addEventListener('change',e=>{const id=e.target.id;if(id==='report-kind'){form.kind=e.target.value;form.location='';form.checked=false;render();}if(id==='report-location'){form.location=e.target.value;form.checked=false;}if(id==='report-assistance'){form.assistance=e.target.checked;form.checked=false;}if(id==='report-wheelchair'){form.wheelchair=e.target.checked;if(form.wheelchair)form.assistance=true;form.checked=false;render();}if(id==='report-checked')form.checked=e.target.checked;else if(id.startsWith('report-')&&$('report-checked'))$('report-checked').checked=form.checked;});
  document.addEventListener('submit',async e=>{if(!['field-form','field-confirm-form','modal-form'].includes(e.target.id))return;e.preventDefault();try{
    if(e.target.id==='field-form'){prepareManualReport();return;}
    if(e.target.id==='field-confirm-form'){await submitFieldPrepared();return;}
    const m=modal;if(!m)throw new Error('请重新打开操作');let payload={},name=m.kind;
    if(m.kind==='confirm'){if(!$('modal-check').checked)throw new Error('请先核对草案');payload={alternative:m.alternative,note:$('modal-note').value};}
    else if(m.kind==='review')payload={id:m.id,decision:$('review-decision').value,note:$('modal-note').value};
    else if(m.kind==='resolve')payload={id:m.id,note:$('modal-note').value,reopen:$('modal-check')?.checked===true};
    else if(m.kind==='edit')payload={id:m.id,kind:m.extra,...(m.extra==='households'?{people:Number($('edit-people').value),risk:Number($('edit-risk').value),assistance:$('edit-assistance').checked,wheelchair:$('edit-wheelchair').checked}:{capacity:Number($('edit-capacity').value),available:$('edit-available').checked,wheelchair:$('edit-wheelchair')?.checked===true})};
    else if(m.kind==='village-review'||m.kind==='village-complete'){payload={id:m.id,note:$('village-note').value,...(m.kind==='village-review'?{decision:$('village-decision').value}:{})};if($('vreview-pickup'))Object.assign(payload,{pickupId:$('vreview-pickup').value,assistancePeople:nullableNumber($('vreview-assistance').value),wheelchairPeople:nullableNumber($('vreview-wheelchair').value),groupPolicy:$('vreview-group').value});}
    else if(m.kind==='reset'){if(!$('modal-check').checked)throw new Error('请先确认重置');}
    else return;
    await action(name,payload,m.revision,m.session);$('dialog').close();modal=null;notify('操作已保存，两个网页将同步更新。');
  }catch(error){if(e.target.id==='modal-form')$('modal-error').textContent=error.message+(state&&modal&&modal.revision!==d().revision?'。请关闭后重新打开核对。':'');else notify(error.message);}});
  async function clickAction(el){const ac=el.dataset.ac,id=el.dataset.id;if(el.disabled)return;
    if(ac==='retry'){await poll();return;}if(!state)return;
    if(ac.startsWith('field-')&&voice.active())throw new Error('请先结束语音识别并核对内容');
    if(ac.startsWith('village-')){await villageClick(ac,id);return;}
    if(ac==='field-workspace'){fieldWorkspace=id;render();return;}
    if(ac==='field-quick'){prepareFieldQuick(el.dataset.stage,el.dataset.household);return;}
    if(ac==='field-prepare'){prepareFieldUtterance();return;}
    if(ac==='field-clear'){fieldUtterance='';fieldHousehold='';fieldLocation='';fieldPrepared=null;fieldConfirmed=false;render();return;}
    if(ac==='field-scene'&&id==='people'){fieldWorkspace='village';render();$('village-composer')?.scrollIntoView({block:'start'});return;}
    if(ac==='field-scene'){form.text='';form.people='';form.wheelchair=false;form.assistance=false;form.voiceFilled=false;form.kind=id;form.location=(id==='road'?s().edges:s().nodes).some(x=>x.id===fieldLocation)?fieldLocation:'';fieldPrepared=null;fieldConfirmed=false;render();$('report-text').scrollIntoView({block:'center'});$('report-text').focus({preventScroll:true});return;}
    if(ac==='field-live'){$('field-live')?.scrollIntoView({block:'start'});return;}
    if(ac==='field-events-toggle'){allFieldEvents=!allFieldEvents;render();return;}
    if(ac==='field-event'){const event=d().fieldEvents.find(x=>x.id===id);if(event?.kind==='village'){$('village-reports')?.scrollIntoView({block:'start'});highlightResult('village-reports');}else if(event?.kind==='report'){$('reports-panel')?.scrollIntoView({block:'start'});highlightResult('reports-panel');}else{tab='execution';render();$('task-panel')?.scrollIntoView({block:'start'});highlightResult('task-panel');}return;}

    if(ac==='focus-ai'){(view==='field'?(fieldWorkspace==='village'?$('village-composer'):document.querySelector('.field-voice-composer')):$('ai-assistant')).scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});(view==='field'?(fieldWorkspace==='village'?$('village-utterance'):$('field-utterance')):$('chat-input')).focus({preventScroll:true});return;}
    if(ac==='map-mode'){mapMode=id;render();return;}
    if(ac==='close'){$('dialog').close();document.body.classList.remove('printing-report');modal=null;return;}if(ac==='voice'){if(voice.active())voice.stop();else{invalidateFieldDraft();stopSpeech();speechNote='语音输入期间暂停播报';voiceTarget=el.dataset.target||'chat';if(voiceTarget==='village')villagePrepared=null;voice.start();}return;}if(ac==='voice-cancel'){voice.cancel();return;}
    if(ac==='speech-toggle'){autoSpeech=!autoSpeech;lastSpeech=d().lastAnnouncement;if(autoSpeech)speech(lastSpeech);else{stopSpeech();speechNote='自动播报已关闭';}render();return;}
    if(ac==='speech-once'){speech(d().lastAnnouncement);return;}if(ac==='speech-stop'){stopSpeech();speechNote='已停止播报';updateSpeechStatus();return;}
    if(ac==='settings'){openModal('settings');return;}if(ac==='reset-dialog'){openModal('reset');return;}
    if(ac==='map-node'||ac==='map-road'){if(view==='field'){invalidateFieldDraft();form.kind=ac==='map-road'?'road':'people';form.location=id;form.checked=false;render();$('report-text').focus();}else openModal('map',id);return;}
    if(ac==='report-at'){invalidateFieldDraft();form.kind=el.dataset.kind;form.location=id;form.checked=false;fieldWorkspace='tasks';$('dialog').close();modal=null;location.hash='field';return;}
    if(ac==='route'){routeChoice=id;render();return;}if(ac==='tab'){tab=id;render();return;}if(ac==='report'||ac==='evidence'){if(view==='field')location.hash='command';tab=ac;render();requestAnimationFrame(()=>document.querySelector('.tabs')?.scrollIntoView({block:'start'}));return;}
    if(ac==='export'){exportJSON();return;}if(ac==='print'){const content=reportHTML();$('dialog-content').innerHTML=`<div class="dialog-body"><button class="no-print" data-ac="close">关闭报告</button>${content}</div>`;if(!$('dialog').open)$('dialog').showModal();document.body.classList.add('printing-report');window.print();return;}
    if(['confirm','review','resolve','edit'].includes(ac)){openModal(ac,id,el.dataset.kind);return;}if(ac==='alternative'){showAlternative=!showAlternative;render();return;}
    if(ac==='prompt'){if(voice.active())return;chatDraft=(view==='field'?['如何填写现场反馈','总结当前情况','查看处理结果']:['总结当前情况','为什么这样安排','生成新草案'])[Number(id)];render();$('chat-input').focus();return;}if(ac==='chat-send'){await sendChat();return;}
    if(ac==='chat-action'){if(voice.active())throw new Error('请先结束语音识别，再使用建议操作');const m=messages.find(x=>x.id===id);if(!m||m.revision!==d().revision)throw new Error('依据已更新，请重新提问');if(m.action==='show-reports'){$('reports-panel').scrollIntoView({block:'start'});}else if(m.action==='open-report'){$('report-text').scrollIntoView({block:'center'});$('report-text').focus({preventScroll:true});}else if(m.action==='fill-report'){invalidateFieldDraft();form.voiceFilled=false;form.text=m.sourceText;form.checked=false;render();$('report-text').scrollIntoView({block:'center'});$('report-text').focus({preventScroll:true});}else if(m.action==='generate')await action('generate');else if(m.action==='alternative'){showAlternative=true;view='command';history.replaceState(null,'','#command');render();$('planning-panel').scrollIntoView({block:'start'});}else if(m.action==='settings')openModal('settings');else{tab='evidence';view='command';history.replaceState(null,'','#command');render();document.querySelector('.tabs')?.scrollIntoView({block:'start'});}return;}
    if(ac==='parse-report'){parseReport();return;}if(ac==='sample'){invalidateFieldDraft();form.voiceFilled=false;form.text=form.kind==='people'?'东桥西新增 2 人，需要人员陪同接送。':form.kind==='road'?'演练东桥有倒树，车辆无法通行。':form.kind==='medical'?'东桥西有人需要医疗协助，请联系专业人员。':form.kind==='hazard'?'东桥西发现积水险情，请核实现场情况。':'现场情况已登记，请补充具体位置和事实。';form.checked=false;render();return;}
    if(ac==='contact-all'){await action('contact',{ids:s().households.filter(h=>d().stage[h.id]==='waiting'&&!d().contacts[h.id]?.contacted).map(h=>h.id)});notify('已登记演练联系结果；尚不代表完成转移。');return;}
    if(ac==='generate')await action('generate');else if(ac==='weather')await action('weather',{preset:id});else if(ac==='start')await action('start');else if(ac==='step')await action('step',{vehicleId:id});else if(ac==='verify')await action('verify',{id});
  }
  document.addEventListener('click',e=>{const el=e.target.closest('[data-ac]');if(!el)return;e.preventDefault();clickAction(el).catch(error=>notify(error.message));});
  document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendChat().catch(x=>notify(x.message));}if(e.target.matches('[role="button"][data-ac]')&&['Enter',' '].includes(e.key)){e.preventDefault();clickAction(e.target).catch(x=>notify(x.message));}});
  window.addEventListener('afterprint',()=>document.body.classList.remove('printing-report'));
  $('dialog').addEventListener('close',()=>document.body.classList.remove('printing-report'));
  window.addEventListener('hashchange',()=>{if(voice.active())voice.cancel('已切换页面，原输入已保留。',false);view=location.hash==='#field'?'field':'command';render();window.scrollTo(0,0);});
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&voice.active())voice.cancel('离开前台，语音输入已停止。');});
  window.addEventListener('pagehide',()=>{voice.cancel('',false);stopSpeech();eventStream?.close();eventStream=null;liveConnected=false;});window.addEventListener('pageshow',()=>{connectEvents();render();});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll(true);});
  window.addEventListener('scroll',updateAiLauncher,{passive:true});window.addEventListener('resize',updateAiLauncher);
  render();poll();setInterval(poll,1200);
})();
